create or replace function public.rr_upm_finalize_submit_handover_v327(p_request_id uuid,p_count_rows jsonb,p_resolution text default 'EXACT_RECEIVER_COUNT') returns jsonb language sql security definer set search_path to 'public' as $function$ select public.rr_upm_finalize_submit_handover_v689(p_request_id,p_count_rows,p_resolution)||jsonb_build_object('compatibility_alias','V327_TO_V689') $function$;

