create or replace function public.rr_thread_cone_costing_v704(p_pcs numeric,p_data_mode text default 'TEST') returns jsonb language sql stable security definer set search_path to 'public' as $function$ select jsonb_build_object('ok',true,'version','V704_THREAD_FOC_ALIAS','state','FOC_AUTHORITY','fixed_cost_per_pc',1.50,'lot_pcs',p_pcs,'lot_cost',round(p_pcs*1.5,2),'costing_head','FOC','inventory_reconciliation','SEPARATE_PURCHASE_STOCK_ANALYTICS','rule','THREAD PRODUCT COST IS INCLUDED ONCE INSIDE FOC; DO NOT ADD AS SEPARATE PRODUCT COMPONENT') $function$;
create or replace function public.rr_fg_pack_plan_box_cost_trigger_v259() returns trigger language plpgsql as $function$ begin raise exception 'RETIRED V721: automatic first-box trigger is disabled; packer-selected V686 binding required.';end $function$;
